public abstract class BuckRuleComposer {

  protected BuckRuleComposer() {}

  public static Set<String> external(Set<OExternalDependency> deps) {
    return deps.stream().map(BuckRuleComposer::external).collect(Collectors.toSet());
  }

  public static String external(OExternalDependency dep) {
    try {
      return String.format("//%s:%s", dep.getTargetPath(), dep.getTargetName());
    } catch (NullPointerException e) {
      throw new IllegalStateException(e);
    }
  }

  public static Set<String> externalApt(Set<OExternalDependency> deps) {
    return external(deps);
  }

  public static Set<String> targets(Set<Target> deps) {
    return deps.stream().map(BuckRuleComposer::targets).collect(Collectors.toSet());
  }

  private static String targets(Target dep) {
    return String.format("//%s:src_%s", dep.getPath(), dep.getName());
  }

  public static Set<String> targetsApt(Set<Target> deps) {
    return deps.stream()
        .filter(target -> target.getClass().equals(JvmTarget.class))
        .map(BuckRuleComposer::targets)
        .collect(Collectors.toSet());
  }

  public static String binTargets(Target dep) {
    return String.format("//%s:bin_%s", dep.getPath(), dep.getName());
  }

  @Nullable
  public static String fileRule(@Nullable String fileString) {
    if (fileString == null) {
      return null;
    }

    Path filePath = Paths.get(fileString);
    Path parentFilePath = filePath.getParent();

    if (parentFilePath == null) {
      return String.format("//:%s", filePath);
    } else {
      return String.format("//%s:%s", parentFilePath, parentFilePath.relativize(filePath));
    }
  }
}

package com.uber.okbuck.composer.java;

import static com.uber.okbuck.core.dependency.OExternalDependency.filterJar;

import com.google.common.collect.ImmutableSet;
import com.uber.okbuck.composer.jvm.JvmBuckRuleComposer;
import com.uber.okbuck.core.model.base.RuleType;
import com.uber.okbuck.core.model.base.Scope;
import com.uber.okbuck.template.core.Rule;
import com.uber.okbuck.template.java.JavaAnnotationProcessorRule;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;

public class JavaAnnotationProcessorRuleComposer extends JvmBuckRuleComposer {

  JavaAnnotationProcessorRuleComposer() {}

  /**
   * Uses the annotation processors scope list to generate the java_annotation_processor rules. It
   * sorts them based on the the annotation processor's UID.
   *
   * @param scopeList List of annotation processor scopes.
   * @return A list containing java_annotation_processor rules.
   */
  public static List<Rule> compose(Collection<Scope> scopeList) {
    return scopeList
        .stream()
        .filter(scope -> !scope.getAnnotationProcessors().isEmpty())
        .sorted(
            (scope1, scope2) ->
                scope1
                    .getAnnotationProcessorPlugin()
                    .pluginUID()
                    .compareToIgnoreCase(scope2.getAnnotationProcessorPlugin().pluginUID()))
        .map(
            scope -> {
              ImmutableSet.Builder<String> depsBuilder = new ImmutableSet.Builder<>();
              depsBuilder.addAll(externalApt(filterJar(scope.getExternalDeps())));
              depsBuilder.addAll(targetsApt(scope.getTargetDeps()));

              return new JavaAnnotationProcessorRule()
                  .processorClasses(scope.getAnnotationProcessors())
                  .name(getApPluginRuleName(scope.getAnnotationProcessorPlugin()))
                  .deps(depsBuilder.build())
                  .ruleType(RuleType.JAVA_ANNOTATION_PROCESSOR.getBuckName());
            })
        .collect(Collectors.toList());
  }
}

package com.uber.okbuck.composer.java;

import static com.uber.okbuck.core.dependency.OResolvedDependency.AAR;
import static com.uber.okbuck.core.dependency.OResolvedDependency.JAR;

import com.uber.okbuck.composer.jvm.JvmBuckRuleComposer;
import com.uber.okbuck.core.dependency.OExternalDependency;
import com.uber.okbuck.core.model.base.RuleType;
import com.uber.okbuck.template.core.Rule;
import com.uber.okbuck.template.java.NativePrebuilt;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;

public class LocalPrebuiltRuleComposer extends JvmBuckRuleComposer {
  /**
   * @param dependencies Local Dependencies whose rule needs to be created
   * @return List of rules
   */
  @SuppressWarnings("NullAway")
  public static List<Rule> compose(Collection<OExternalDependency> dependencies) {
    return dependencies
        .stream()
        .sorted(OExternalDependency.compareByName)
        .map(
            dependency -> {
              RuleType ruleType;

              switch (dependency.getPackaging()) {
                case JAR:
                  ruleType = RuleType.PREBUILT_JAR;
                  break;
                case AAR:
                  ruleType = RuleType.ANDROID_PREBUILT_AAR;
                  break;
                default:
                  throw new IllegalStateException("Dependency not a valid prebuilt: " + dependency);
              }

              String source;
              if (dependency.getRealSourceFile().isPresent()) {
                source = dependency.getSourceFileName();
              } else {
                source = null;
              }

              return new NativePrebuilt()
                  .prebuiltType(ruleType.getProperties().get(0))
                  .prebuilt(dependency.getDependencyFileName())
                  .mavenCoords(dependency.getMavenCoords())
                  .enableJetifier(dependency.enableJetifier())
                  .source(source)
                  .ruleType(ruleType.getBuckName())
                  .deps(external(dependency.getDeps()))
                  .name(dependency.getTargetName());
            })
        .collect(Collectors.toList());
  }
}

package com.uber.okbuck.composer.android;

import com.uber.okbuck.composer.jvm.JvmBuckRuleComposer;
import com.uber.okbuck.core.model.android.AndroidAppTarget;
import com.uber.okbuck.core.model.android.AndroidTarget;
import com.uber.okbuck.core.model.base.Target;
import java.util.Set;
import java.util.stream.Collectors;

public abstract class AndroidBuckRuleComposer extends JvmBuckRuleComposer {

  public static String res(AndroidTarget target) {
    return "res_" + target.getName();
  }

  static String resRule(AndroidTarget target) {
    return "//" + target.getPath() + ":" + res(target);
  }

  static String buildConfig(AndroidTarget target) {
    return "build_config_" + target.getName();
  }

  static String prebuiltNative(AndroidTarget target, String jniLibDir) {
    return "prebuilt_native_library_" + target.getName() + "_" + jniLibDir.replaceAll("/", "_");
  }

  public static String aidl(AndroidTarget target, String aidlDir) {
    return target.getName() + "_" + aidlDir.replaceAll("[/-]", "_") + "_aidls";
  }

  public static String libManifest(AndroidTarget target) {
    return "manifest_lib_" + target.getName();
  }

  static String binManifest(AndroidTarget target) {
    return "manifest_bin_" + target.getName();
  }

  public static String keystore(AndroidTarget target) {
    return "keystore_" + target.getName();
  }

  static String appLib(AndroidTarget target) {
    return "app_lib_" + target.getName();
  }

  public static String bin(AndroidAppTarget target) {
    return "bin_" + target.getName();
  }

  public static String instrumentation(AndroidAppTarget target) {
    return "instrumentation_" + target.getName() + "_apk";
  }

  static String instrumentationTest(AndroidAppTarget target) {
    return "instrumentation_" + target.getName() + "_test";
  }

  static Set<String> resources(Set<Target> targets) {
    return targets
        .stream()
        .filter(targetDep -> targetDep instanceof AndroidTarget)
        .map(targetDep -> resRule((AndroidTarget) targetDep))
        .collect(Collectors.toSet());
  }
}

package com.uber.okbuck.composer.common;

import com.google.common.base.Preconditions;
import com.uber.okbuck.core.dependency.OExternalDependency;
import com.uber.okbuck.template.common.HttpFile;
import com.uber.okbuck.template.core.Rule;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.stream.Collectors;

public class HttpFileRuleComposer {

  private HttpFileRuleComposer() {}

  /**
   * @param dependencies External Dependencies whose http file rule needs to be created
   * @return List of rules
   */
  public static List<Rule> compose(
      Collection<OExternalDependency> dependencies, HashMap<String, String> shaSum256) {
    return dependencies
        .stream()
        .sorted(OExternalDependency.compareByName)
        .map(
            dependency -> {
              String sha256Key =
                  OExternalDependency.getGradleSha(dependency.getRealDependencyFile());
              String sha256 = Preconditions.checkNotNull(shaSum256.get(sha256Key));

              Rule rule =
                  new HttpFile()
                      .mavenCoords(dependency.getMavenCoords())
                      .sha256(sha256)
                      .name(dependency.getTargetName());
              rule.name(dependency.getTargetName());
              return rule;
            })
        .collect(Collectors.toList());
  }
}
